parameters.jsCode:
// Normalize person-level de-anon payloads from two sources:
// 1. RB2B webhook (person-level US reveal) — has Business Email, Captured URL, Seen At
// 2. Warmly webhook (contact + company nesting) — has contact.linkedInUrl, company.*
// 3. Generic fallback for anything else that can POST a person shape.
//
// Output: one normalized person record regardless of source.

const raw = $json.body || $json;

let source = 'unknown';
let firstName = '';
let lastName = '';
let title = '';
let company = '';
let domain = '';
let email = '';
let linkedinUrl = '';
let employeeCount = null;
let industry = '';
let country = '';
let pageViewed = '';
let referrer = '';

const stripDomain = (u) => (u || '').replace(/^https?:\/\/(www\.)?/, '').split('/')[0];

if (raw['Business Email'] !== undefined || raw['Captured URL'] !== undefined) {
  // RB2B webhook shape (space-cased field names)
  source = 'rb2b';
  firstName = raw['First Name'] || '';
  lastName = raw['Last Name'] || '';
  title = raw['Title'] || '';
  company = raw['Company Name'] || '';
  domain = stripDomain(raw['Website'] || '');
  email = raw['Business Email'] || '';
  linkedinUrl = raw['LinkedIn URL'] || '';
  employeeCount = parseInt(raw['Employee Count'], 10) || null;
  industry = raw['Industry'] || '';
  country = raw['Country'] || (raw['State'] ? 'US' : '');
  pageViewed = raw['Captured URL'] || '';
  referrer = raw['Referrer'] || '';

} else if (raw.contact || raw.company) {
  // Warmly webhook shape (nested contact + company)
  source = 'warmly';
  const c = raw.contact || {};
  const co = raw.company || {};
  const sig = raw.signal || {};
  firstName = c.firstName || c.first_name || '';
  lastName = c.lastName || c.last_name || '';
  title = c.title || '';
  company = co.name || '';
  domain = stripDomain(co.website || co.domain || '');
  email = c.businessEmail || c.email || '';
  linkedinUrl = c.linkedInUrl || c.linkedinUrl || '';
  employeeCount = parseInt(co.employeeCount || co.employee_count, 10) || null;
  industry = co.industry || '';
  country = c.country || co.country || '';
  pageViewed = sig.capturedUrl || sig.referrer || '';
  referrer = sig.referrer || '';

} else {
  // Generic fallback
  source = 'generic';
  firstName = raw.firstName || raw.first_name || '';
  lastName = raw.lastName || raw.last_name || '';
  title = raw.title || '';
  company = raw.company || raw.company_name || raw.companyName || '';
  domain = stripDomain(raw.website || raw.domain || '');
  email = raw.email || raw.businessEmail || '';
  linkedinUrl = raw.linkedinUrl || raw.linkedInUrl || raw.linkedin_url || '';
  employeeCount = parseInt(raw.employeeCount || raw.employee_count, 10) || null;
  industry = raw.industry || '';
  country = raw.country || '';
  pageViewed = raw.pageViewed || raw.capturedUrl || raw.captured_url || '';
  referrer = raw.referrer || '';
}

// Identity key: prefer email, fall back to LinkedIn URL, then name+domain.
const identityKey = (email || linkedinUrl || `${firstName}${lastName}@${domain}`).toLowerCase();

if (!identityKey || identityKey === '@') {
  throw new Error('Normalized payload has no usable identity (email / LinkedIn / name+domain) — cannot process reveal.');
}

return [{
  json: {
    source,
    firstName,
    lastName,
    fullName: `${firstName} ${lastName}`.trim(),
    title,
    company,
    domain,
    email,
    linkedinUrl,
    employeeCount,
    industry,
    country,
    pageViewed,
    referrer,
    identityKey,
    receivedAt: new Date().toISOString()
  }
}];

// ICP Fit Gate — the node that separates this flow from a plain intent router.
// Scores the identified person against a readable, editable rubric. Anyone below
// ICP_FIT_THRESHOLD is dropped (return []) and never reaches a rep.
//
// All thresholds come from env vars with in-code fallbacks so the flow never throws.
// fitScore and reasons are attached to the record so a passing visitor's Slack card
// shows WHY they qualified, and a misconfigured rubric is auditable.

const p = $json;

const minEmp = parseInt($env.ICP_MIN_EMPLOYEES, 10) || 25;
const maxEmp = parseInt($env.ICP_MAX_EMPLOYEES, 10) || 5000;
const threshold = parseInt($env.ICP_FIT_THRESHOLD, 10) || 3;

// Country allowlist (comma-separated ISO codes). Empty env → allow all.
const countryAllow = ($env.ICP_COUNTRY_ALLOWLIST || '')
  .split(',').map(s => s.trim().toUpperCase()).filter(Boolean);

// Title function allow / deny (comma-separated lowercase substrings).
const titleAllow = ($env.ICP_TITLE_ALLOWLIST ||
  'revops,revenue operations,sales,marketing,growth,demand,founder,ceo,cofounder,product')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const titleDeny = ($env.ICP_TITLE_DENYLIST ||
  'student,intern,seeking,recruiter,talent acquisition,job')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const titleLc = (p.title || '').toLowerCase();
const pageLc = (p.pageViewed || '').toLowerCase();

let score = 0;
const reasons = [];

// Hard deny on title — an agency recruiter or job-seeker is never in-ICP.
if (titleDeny.some(d => titleLc.includes(d))) {
  return []; // drop silently
}

// Title function match (+2)
if (titleAllow.some(a => titleLc.includes(a))) { score += 2; reasons.push('title-function'); }

// Seniority (+1)
if (/(chief|c[erefoit]o|founder|vp|vice president|head of|director)/i.test(titleLc)) {
  score += 1; reasons.push('seniority');
}

// Company-size band (+1)
if (p.employeeCount !== null && p.employeeCount >= minEmp && p.employeeCount <= maxEmp) {
  score += 1; reasons.push('size-band');
}

// Country allowlist (+1 if allowed; hard drop if a list is set and country is off it)
if (countryAllow.length) {
  if (p.country && countryAllow.includes((p.country || '').toUpperCase())) {
    score += 1; reasons.push('country');
  } else if (p.country) {
    return []; // country set and not on the allowlist — drop
  }
}

// Page intent (+2 for a high-intent page)
if (/(pricing|demo|request|contact-sales|product|trial)/.test(pageLc)) {
  score += 2; reasons.push('high-intent-page');
}

if (score < threshold) {
  // Below the fit bar — drop silently. (Log via execution history if needed.)
  return [];
}

return [{ json: { ...p, fitScore: score, fitReasons: reasons } }];

// Week-level dedup using n8n workflow static data — the only correct way to persist
// cross-execution state from a Code node (n8n's public REST API has NO static-data resource).
//
// Week-level (not day-level) is the right window for warm outreach: a person who visits
// three times in five days should generate ONE rep touch, not three.
//
// NOTE: static data persists only for PRODUCTION executions (webhook / schedule trigger),
// not manual Execute Workflow runs — verify dedup against the live webhook.

const staticData = $getWorkflowStaticData('global');
const p = $json;

// ISO week key: YYYY-Www
const d = new Date();
const tmp = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
const dayNum = (tmp.getUTCDay() + 6) % 7;
tmp.setUTCDate(tmp.getUTCDate() - dayNum + 3);
const firstThursday = tmp.getTime();
tmp.setUTCMonth(0, 1);
if (tmp.getUTCDay() !== 4) {
  tmp.setUTCMonth(0, 1 + ((4 - tmp.getUTCDay()) + 7) % 7);
}
const weekNo = 1 + Math.ceil((firstThursday - tmp.getTime()) / (7 * 24 * 3600 * 1000));
const isoWeek = `${d.getUTCFullYear()}-W${String(weekNo).padStart(2, '0')}`;

const key = `dedup_${p.identityKey}_${isoWeek}`;

// Prune keys from earlier weeks so the store stays small.
for (const k of Object.keys(staticData)) {
  if (k.startsWith('dedup_') && !k.endsWith(`_${isoWeek}`)) {
    delete staticData[k];
  }
}

// Duplicate this week → drop silently.
if (staticData[key]) {
  return [];
}

// Mark BEFORE any external call so two concurrent reveals can't both pass.
staticData[key] = p.receivedAt || new Date().toISOString();

return [{ json: { ...p, dedupPassed: true, isoWeek } }];

// Routing & Suppression Logic.
//
// Suppression (return [] — drop) when the contact EXISTS and any of:
//   - account has an open Opportunity, OR
//   - contact is in an active sequence (Current_Sequence__c set), OR
//   - account Type is 'Customer' / 'Customer - Direct' (existing customer).
// A warm de-anon touch would step on a live motion in these cases.
//
// Otherwise:
//   - contact exists (and clean) → route to account Owner, create a TASK on the contact.
//   - no contact → route to territory SDR pool (AMER/EMEA/ROW), create a LEAD.

const p = $('Dedup Gate (Static Data)').item.json;
const rec = $json?.records?.[0] || null;

if (rec) {
  const acctType = (rec.Account?.Type || '').toLowerCase();
  const inSequence = !!rec.Current_Sequence__c;
  const openOpp = Array.isArray(rec.Opportunities?.records) && rec.Opportunities.records.length > 0;
  const isCustomer = acctType.includes('customer');

  if (inSequence || openOpp || isCustomer) {
    // Live motion in progress — suppress the warm touch.
    return [];
  }

  return [{
    json: {
      ...p,
      createSObject: 'Task',
      sfdcContactId: rec.Id || '',
      sfdcAccountId: rec.AccountId || '',
      sfdcAccountName: rec.Account?.Name || p.company,
      sfdcOwnerId: rec.Owner?.Id || '',
      assigneeName: rec.Owner?.Name || 'Account Owner',
      assigneeEmail: rec.Owner?.Email || '',
      assigneeSlack: rec.Owner?.Slack_Handle__c || '',
      assignmentSource: 'sfdc-existing-owner',
      contactFound: true
    }
  }];
}

// No contact — territory pool assignment for a net-new Lead.
const country = (p.country || '').toUpperCase();
const amer = new Set(['US', 'CA', 'AU', 'NZ', 'MX', 'BR', 'AR', 'CL', 'CO']);
const emea = new Set(['DE', 'AT', 'CH', 'FR', 'NL', 'SE', 'DK', 'NO', 'FI', 'BE', 'GB', 'IE', 'ES', 'PT', 'IT']);

let assigneeEmail, assigneeName, assigneeSlack, assignmentSource;
if (amer.has(country) || country === '') {
  assigneeEmail = $env.SDR_POOL_AMER_EMAIL || 'sdr-amer@example.com';
  assigneeName = 'SDR Pool — AMER';
  assigneeSlack = $env.SDR_POOL_AMER_SLACK || '';
  assignmentSource = 'pool-amer';
} else if (emea.has(country)) {
  assigneeEmail = $env.SDR_POOL_EMEA_EMAIL || 'sdr-emea@example.com';
  assigneeName = 'SDR Pool — EMEA';
  assigneeSlack = $env.SDR_POOL_EMEA_SLACK || '';
  assignmentSource = 'pool-emea';
} else {
  assigneeEmail = $env.SDR_POOL_ROW_EMAIL || 'sdr-row@example.com';
  assigneeName = 'SDR Pool — ROW';
  assigneeSlack = $env.SDR_POOL_ROW_SLACK || '';
  assignmentSource = 'pool-row';
}

return [{
  json: {
    ...p,
    createSObject: 'Lead',
    sfdcContactId: '',
    sfdcAccountId: '',
    sfdcAccountName: p.company,
    sfdcOwnerId: '',
    assigneeName,
    assigneeEmail,
    assigneeSlack,
    assignmentSource,
    contactFound: false
  }
}];

parameters.jsonBody:
={
  "model": "claude-haiku-4-5",
  "max_tokens": 600,
  "system": "You write short, specific warm first-touch outreach for B2B SDRs acting on a website visit that a de-anonymization tool just identified. Given the person, their role, their company, and the exact page they viewed, produce a single JSON object with three fields: {\"subject\": string under 60 chars, \"body\": string under 240 chars, \"talking_point\": string under 120 chars}. The body MUST reference the specific page the person viewed and their role — the whole point is that they were just on your site. Do not use: 'I noticed', 'reach out', 'touch base', 'circle back', 'synergy', 'leverage', 'empower'. This is a starting point the SDR edits and the identity is probabilistic, so keep claims light. Tone: direct, peer-to-peer, no fluff. Reply with JSON only, no prose, no code fences.",
  "messages": [
    {
      "role": "user",
      "content": "Person: {{ $json.fullName }}\nTitle: {{ $json.title }}\nCompany: {{ $json.sfdcAccountName }}\nIndustry: {{ $json.industry }}\nEmployee count: {{ $json.employeeCount }}\nCountry: {{ $json.country }}\nPage viewed: {{ $json.pageViewed }}\nReferrer: {{ $json.referrer }}\nDe-anon source: {{ $json.source }}\nICP fit reasons: {{ JSON.stringify($json.fitReasons) }}"
    }
  ]
}

parameters.jsCode:
// Parse Claude's draft; fall back to a template if parsing fails.
const d = $('Routing & Suppression Logic').item.json;
const raw = $json?.content?.[0]?.text || '';

let draft = null;
try { draft = JSON.parse(raw); } catch (e) { draft = null; }

const usedFallback = !draft || !draft.subject;
const pagePart = d.pageViewed ? d.pageViewed.replace(/^https?:\/\/[^/]+/, '') : 'your site';
const subject = draft?.subject || `Saw you on ${pagePart} — quick note`;
const body = draft?.body || `Hi ${d.firstName || 'there'}, saw someone from ${d.sfdcAccountName} was on ${pagePart}. If you're weighing options, happy to share what's worked for similar ${d.industry || 'teams'} — no pitch.`;
const talkingPoint = draft?.talking_point || `${d.fullName} (${d.title}) at ${d.sfdcAccountName} viewed ${pagePart}. Fit reasons: ${(d.fitReasons || []).join(', ')}.`;

return [{
  json: {
    ...d,
    draftSubject: subject,
    draftBody: body,
    draftTalkingPoint: talkingPoint,
    draftSource: usedFallback ? 'template-fallback' : 'claude'
  }
}];

parameters.jsonBody:
={
  "channel": "#visitor-deanon",
  "text": ":wave: Warm visitor — {{ $json.fullName }} at {{ $json.sfdcAccountName }} (fit {{ $json.fitScore }})",
  "blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": ":wave: *{{ $json.fullName }}* — {{ $json.title || 'unknown title' }} at *{{ $json.sfdcAccountName }}*  ·  fit score *{{ $json.fitScore }}* ({{ $json.fitReasons.join(', ') }})\n*Assigned to:* {{ $json.assigneeName }}{{ $json.assigneeSlack ? ' (<@' + $json.assigneeSlack + '>)' : '' }}  ·  {{ $json.contactFound ? 'existing contact → Task' : 'net-new → Lead' }}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Viewed:* {{ $json.pageViewed || 'unknown' }}  ·  *Source:* {{ $json.source }}  ·  *Country:* {{ $json.country || 'unknown' }}  ·  *Headcount:* {{ $json.employeeCount || 'unknown' }}\n*LinkedIn (verify identity):* {{ $json.linkedinUrl || 'none' }}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Draft subject:* {{ $json.draftSubject }}\n*Draft body (edit before sending):* {{ $json.draftBody }}\n*Talking point:* {{ $json.draftTalkingPoint }}\n_Draft source: {{ $json.draftSource }}_"
      }
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "Identity is probabilistic — verify the LinkedIn URL before sending. Reveal received: {{ $json.receivedAt }}"
        }
      ]
    }
  ]
}

={{ (() => {
  const j = $json;
  const notes = `Warm website visitor via ${j.source}.\nViewed: ${j.pageViewed || 'n/a'}\nICP fit: ${j.fitScore} (${(j.fitReasons||[]).join(', ')})\nLinkedIn: ${j.linkedinUrl || 'n/a'}\nDraft subject: ${j.draftSubject}\nDraft body: ${j.draftBody}\nTalking point: ${j.draftTalkingPoint}\nDraft source: ${j.draftSource}\nAssignment: ${j.assignmentSource}`;
  if (j.createSObject === 'Lead') {
    const lead = {
      FirstName: j.firstName || 'Unknown',
      LastName: j.lastName || j.company || 'Unknown',
      Company: j.company || 'Unknown',
      Title: j.title || '',
      Email: j.email || '',
      Website: j.domain ? `https://${j.domain}` : '',
      Country: j.country || '',
      NumberOfEmployees: j.employeeCount != null ? j.employeeCount : null,
      Industry: j.industry || '',
      LeadSource: 'Website Visitor (de-anon)',
      Description: notes
    };
    return JSON.stringify(lead);
  }
  // Task on an existing contact.
  const task = {
    Subject: `Warm visitor: ${j.fullName} viewed ${ (j.pageViewed||'site').replace(/^https?:\/\/[^/]+/, '') }`,
    Description: notes,
    Priority: j.fitScore >= 5 ? 'High' : 'Normal',
    Status: 'Not Started',
    ActivityDate: $now.plus({ days: 2 }).toFormat('yyyy-MM-dd'),
    Type: 'Email',
    WhoId: j.sfdcContactId || undefined,
    WhatId: j.sfdcAccountId || undefined
  };
  if (j.sfdcOwnerId) task.OwnerId = j.sfdcOwnerId;
  Object.keys(task).forEach(k => task[k] === undefined && delete task[k]);
  return JSON.stringify(task);
})() }}
